The program follows the standard benchmarks-game `binary-trees` algorithm:

- **Depths:** `minDepth` is 4 and `maxDepth` is `Math.Max(minDepth + 2, N)`.
- **Stretch tree:** one tree of depth `maxDepth + 1` is built and checked first. Its count is printed before anything else.
- **Long-lived tree:** one tree of depth `maxDepth` is built next and kept alive until the end.
- **Short-lived trees:** for each depth `d` = 4, 6, …, `maxDepth`, the program builds `2^(maxDepth - d + minDepth)` trees. It sums their node counts.
- **Parallelism:** each depth runs as its own parallel task, and the results go into an array. That array is printed in order, so the output stays deterministic.
- **Load balance:** every depth group allocates roughly the same total number of nodes, so the per-depth work is fairly even.

```csharp
using System;
using System.Text;
using System.Threading.Tasks;

sealed class Node
{
    public Node Left, Right;
    public Node(Node l, Node r) { Left = l; Right = r; }

    public static Node Create(int d)
    {
        if (d == 0) return new Node(null, null);
        return new Node(Create(d - 1), Create(d - 1));
    }

    public int Check()
    {
        int c = 1;
        Node n = this;
        while (n.Left != null)
        {
            c += 1 + n.Right.Check();
            n = n.Left;
        }
        return c;
    }
}

static class Program
{
    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        const int minDepth = 4;
        int maxDepth = Math.Max(minDepth + 2, n);
        int stretchDepth = maxDepth + 1;

        var sb = new StringBuilder();
        {
            var st = Node.Create(stretchDepth);
            sb.Append("stretch tree of depth ").Append(stretchDepth).Append("\t check: ").Append(st.Check()).Append('\n');
        }

        var longLived = Node.Create(maxDepth);

        int count = (maxDepth - minDepth) / 2 + 1;
        var results = new string[count];
        Parallel.For(0, count, i =>
        {
            int d = minDepth + i * 2;
            int iterations = 1 << (maxDepth - d + minDepth);
            long check = 0;
            for (int k = 0; k < iterations; k++)
                check += Node.Create(d).Check();
            results[i] = iterations + "\t trees of depth " + d + "\t check: " + check;
        });

        foreach (var r in results) sb.Append(r).Append('\n');
        sb.Append("long lived tree of depth ").Append(maxDepth).Append("\t check: ").Append(longLived.Check()).Append('\n');
        Console.Out.Write(sb.ToString());
    }
}
```

