**Approach**

1. **Formula.** It uses π = 16·atan(1/5) − 4·atan(1/239). Each arctangent is the alternating series atan(1/x) = Σ (−1)^k / ((2k+1)·x^(2k+1)).
2. **Scaling.** Every quantity is scaled by 10^(N+20), so the arithmetic is exact integer work on `BigInteger`. The 20 extra digits absorb the small truncation error left by each integer division.
3. **Cost.** Each term needs only divisions of a big number by a small integer, which take linear time. The atan(1/5) series needs about N/1.4 terms, and the atan(1/239) series about N/4.8. For N = 10000 this runs very fast.
4. **Output.**
   - The scaled result is turned into a string and the first N characters are kept, starting with "31415…".
   - Digits are printed 10 per line, followed by `\t:index`.
   - If the last line has fewer than 10 digits, it is padded with spaces, as in the standard benchmark format.

```csharp
using System;
using System.Numerics;
using System.Text;

class Program
{
    static BigInteger Atan(int x, BigInteger unity)
    {
        BigInteger sum = BigInteger.Zero;
        BigInteger term = unity / x;
        BigInteger x2 = (BigInteger)x * x;
        int k = 0;
        while (!term.IsZero)
        {
            BigInteger t = term / (2 * k + 1);
            if ((k & 1) == 0) sum += t; else sum -= t;
            term /= x2;
            k++;
        }
        return sum;
    }

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        int guard = 20;
        BigInteger unity = BigInteger.Pow(10, n + guard);
        BigInteger pi = 16 * Atan(5, unity) - 4 * Atan(239, unity);
        string s = pi.ToString();
        string digits = s.Substring(0, n);

        var sb = new StringBuilder(n + n / 10 * 8 + 32);
        int i = 0;
        while (i < n)
        {
            int len = Math.Min(10, n - i);
            sb.Append(digits, i, len);
            if (len < 10) sb.Append(' ', 10 - len);
            i += len;
            sb.Append("\t:").Append(i).Append('\n');
        }
        Console.Out.Write(sb.ToString());
        Console.Out.Flush();
    }
}
