The program reads all of stdin, reverse-complements each FASTA record and writes the result in one buffered pass.

1. **Read input.** Stdin is read fully into a byte array. N from `args[0]` is parsed but not otherwise needed, since the input stream defines the work.
2. **Complement table.** A 256-entry lookup maps each IUPAC code to its complement:
   - A↔T, C↔G, U→A, R↔Y, K↔M, B↔V, D↔H.
   - S, W and N map to themselves.
   - Lowercase letters map to the uppercase complement.
   - Any other byte maps to itself.
3. **Per record.**
   - The header line is copied through unchanged.
   - Sequence bytes are gathered with newlines and `\r` removed.
   - They are then emitted in reverse, complemented, wrapped at 60 characters per line.
   - 60 is the width of the input the fasta generator produces, so this preserves the original line-wrapping.
4. **Edge cases.** A partial final line still gets a trailing newline. Empty sequences produce no extra blank line.

```csharp
using System;
using System.IO;

class Program
{
    static void Main(string[] args)
    {
        int n = args.Length > 0 ? int.Parse(args[0]) : 0;
        byte[] data;
        using (var stdin = Console.OpenStandardInput())
        using (var ms = new MemoryStream(1 << 20))
        {
            stdin.CopyTo(ms, 1 << 20);
            data = ms.GetBuffer();
            int l = (int)ms.Length;
            if (data.Length != l) Array.Resize(ref data, l);
        }
        int len = data.Length;

        byte[] map = new byte[256];
        for (int i = 0; i < 256; i++) map[i] = (byte)i;
        string from = "ACGTUMRWSYKVHDBN";
        string to   = "TGCAAKYWSRMBDHVN";
        for (int i = 0; i < from.Length; i++)
        {
            map[from[i]] = (byte)to[i];
            map[char.ToLower(from[i])] = (byte)to[i];
        }

        var stdout = Console.OpenStandardOutput();
        byte[] seq = new byte[Math.Max(16, len)];
        byte[] outBuf = new byte[Math.Max(16, len + len / 60 + 16)];
        int pos = 0;
        while (pos < len)
        {
            if (data[pos] != (byte)'>') { pos++; continue; }
            int hEnd = Array.IndexOf(data, (byte)'\n', pos);
            if (hEnd < 0) hEnd = len - 1;
            stdout.Write(data, pos, hEnd - pos + 1);
            if (data[hEnd] != (byte)'\n') stdout.WriteByte((byte)'\n');
            pos = hEnd + 1;
            int sl = 0;
            while (pos < len && data[pos] != (byte)'>')
            {
                byte b = data[pos++];
                if (b != (byte)'\n' && b != (byte)'\r') seq[sl++] = b;
            }
            int o = 0;
            int col = 0;
            for (int i = sl - 1; i >= 0; i--)
            {
                outBuf[o++] = map[seq[i]];
                if (++col == 60) { outBuf[o++] = (byte)'\n'; col = 0; }
            }
            if (col > 0) outBuf[o++] = (byte)'\n';
            stdout.Write(outBuf, 0, o);
        }
        stdout.Flush();
    }
}
