                double d = transpose ? s * (s + 1) * 0.5 + j + 1 : s * (s + 1) * 0.5 + i + 1;
                sum += v[j] / d;
            }
            outv[i] = sum;
        });
    }

    static void MulAtAv(double[] v, double[] outv, double[] tmp, int n)
    {
        MulAv(v, tmp, n, false);
        MulAv(tmp, outv, n, true);
    }

    static void Main(string[] args)
    {
        int n = int.Parse(args[0]);
        int W = Vector<double>.Count;
        offsets = new double[W];
        for (int k = 0; k < W; k++) offsets[k] = k;

        double[] u = new double[n], v = new double[n], tmp = new double[n];
        for (int i = 0; i < n; i++) u[i] = 1.0;
        for (int it = 0; it < 10; it++)
        {
            MulAtAv(u, v, tmp, n);
            MulAtAv(v, u, tmp, n);
        }
        double vBv = 0, vv = 0;
        for (int i = 0; i < n; i++)
        {
            vBv += u[i] * v[i];
            vv += v[i] * v[i];
        }
        Console.WriteLine(Math.Sqrt(vBv / vv).ToString("F9", CultureInfo.InvariantCulture));
    }
}
